def check_step_overhead_slo(mask_kernel_us: float, unhidden_cpu_us: float, slo_us: float = 50.0) -> bool:
    if mask_kernel_us < 0 or unhidden_cpu_us < 0:
        raise ValueError('Latencies must be non-negative')
    return (mask_kernel_us + unhidden_cpu_us) <= slo_us

def estimate_schema_cache_gb(num_schemas: int, avg_states: int = 40, vocab_size: int = 128256) -> float:
    if num_schemas <= 0 or avg_states <= 0:
        raise ValueError('Schema count and states must be positive')
    bytes_per_state = ((vocab_size + 31) // 32) * 4
    return round((num_schemas * avg_states * bytes_per_state) / 1e9, 3)

import hashlib
import json

def canonical_schema_key(schema: dict) -> str:
    canonical = json.dumps(schema, sort_keys=True, separators=(',', ':'))
    return hashlib.sha256(canonical.encode('utf-8')).hexdigest()

def gather_batch_bitmasks(states: list[int], state_masks: dict[int, bytes]) -> bytearray:
    buf = bytearray()
    for st in states:
        if st not in state_masks:
            raise KeyError(f'Missing compiled bitmask for state {st}')
        buf.extend(state_masks[st])
    return buf

def unpack_bit_allowed(word: int, bit_offset: int) -> bool:
    if not (0 <= bit_offset < 32):
        raise ValueError('bit_offset must be in [0, 31]')
    return bool((word >> bit_offset) & 1)

def plan_decode_or_jump(out_degree: int, jump_tokens: list[int]) -> str:
    if out_degree == 1 and len(jump_tokens) >= 2:
        return f'JUMP_FORWARD_{len(jump_tokens)}_TOKENS'
    return 'SINGLE_TOKEN_MASKED_DECODE'

def check_compile_guard(num_states: int, elapsed_ms: float, max_states: int = 4096, timeout_ms: float = 100.0) -> None:
    if num_states > max_states:
        raise ValueError(f'Schema DFA exceeded state limit ({num_states} > {max_states})')
    if elapsed_ms > timeout_ms:
        raise TimeoutError(f'Schema compilation exceeded {timeout_ms} ms budget')
